// Digital twin for Drive.A.2 — TI DAC63202W smart DAC + 2× TPA2028D1 Class-D amps.
//
// Three ICs, one I²C bus, single V+ supply (pad 10, 2.5–5.5 V):
//   • DAC63202W @ 0x49 (A0 pulled to VDD): two 12-bit DAC channels with an
//     on-chip function generator (triangle/saw/sine), per-channel gain (VREF
//     multiplier), slew/step/phase. CH0 → amp0, CH1 → amp1.
//   • 2× TPA2028D1 @ 0x58 (fixed, SHARED): both amps answer the same address, so
//     amp gain/enable/AGC writes hit BOTH. Each drives a speaker differentially
//     (OUT.0± pads 7/6, OUT.1± pads 9/8).
//
// Signal chain per channel: DAC code → amp (gain dB) → Class-D differential out.
// Speakers are external, so output level + audio power are MODELED; the amp
// quiescent/shutdown currents and the 2.5 W / 90 % max-output point are canonical
// (TPA2028D1 datasheet), as is the DAC conversion code = mv·4096/VREF.
import type { TileSim } from '../tileSim';

const DAC_ADDR = 0x49; // A0 → VDD
const DAC_MAX = 4095;

const WAVE_SINE = 4;
const WAVE_OFF = 7;

// DAC full-scale (mV) per gain code (drive_a_2_gain_t): the VREF table
const GAIN_FS_MV = [3300, 3300, 1815, 2420, 3630, 4840];

// supply currents on V+ (µA)
const I_DAC_ACTIVE_UA = 3000; // DAC63202W active (approx)
const I_DAC_SLEEP_UA = 50; // DAC power-down (approx)
const I_AMP_ACTIVE_UA = 2000; // TPA2028D1 quiescent, enabled (~@5 V) — datasheet
const I_AMP_SHUTDOWN_UA = 0.2; // TPA2028D1 EN-low shutdown — datasheet
const AMP_PMAX_W = 2.5; // max output per channel, 4 Ω / 5 V / 1% THD — datasheet
const AMP_EFF = 0.9; // Class-D efficiency ~90% — datasheet

interface State {
  // ── DAC channel 0 ──
  ch0_code: number; // 12-bit output code
  ch0_gain: number; // gain/VREF select (0..5)
  ch0_wave: number; // function-gen waveform (7 = off)
  ch0_wave_on: number; // function generator running
  ch0_freq: number; // tone frequency (Hz)
  ch0_slew: number;
  ch0_step: number;
  ch0_phase: number;
  ch0_mlo: number;
  ch0_mhi: number;

  // ── DAC channel 1 ──
  ch1_code: number;
  ch1_gain: number;
  ch1_wave: number;
  ch1_wave_on: number;
  ch1_freq: number;
  ch1_slew: number;
  ch1_step: number;
  ch1_phase: number;
  ch1_mlo: number;
  ch1_mhi: number;

  // ── amps (shared) + tile ──
  amp_gain_db: number; // -28..+30
  amp_enabled: number;
  amp_comp: number; // AGC compression ratio
  amp_max_gain: number; // AGC max gain (dB)
  muted: number;
  vplus_mv: number;
  sleeping: number;

  [field: string]: number;
}

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

// Channels a tier-2 call touches (drive_a_2_channel_t: 0 left, 1 right, 2 both).
const chans = (ch: number) => (ch === 2 ? [0, 1] : [clamp(ch, 0, 1)]);

const codeOf = (s: State, ch: number) => (ch === 0 ? s.ch0_code : s.ch1_code);

// Per-channel output drive level 0..1: DAC code × amp linear gain, clipped.
// Zero unless the amps are enabled, un-muted, and the tile is awake.
function outLevel(s: State, ch: number): number {
  if (s.amp_enabled !== 1 || s.muted === 1 || s.sleeping === 1) return 0;
  const norm = codeOf(s, ch) / DAC_MAX;
  const lin = Math.pow(10, s.amp_gain_db / 20);
  return clamp(norm * lin, 0, 1);
}

// Build a nextState patch applying {base: value} to one or both channels.
function chPatch(ch: number, base: string, value: number): Partial<State> {
  const out: Record<string, number> = {};
  for (const c of chans(ch)) out[`ch${c}_${base}`] = value;
  return out as Partial<State>;
}

const sim: TileSim<State> = {
  tile: 'Drive.A.2',

  defaultState: {
    ch0_code: 0,
    ch0_gain: 0,
    ch0_wave: WAVE_OFF,
    ch0_wave_on: 0,
    ch0_freq: 1000,
    ch0_slew: 0,
    ch0_step: 0,
    ch0_phase: 0,
    ch0_mlo: 0,
    ch0_mhi: DAC_MAX,

    ch1_code: 0,
    ch1_gain: 0,
    ch1_wave: WAVE_OFF,
    ch1_wave_on: 0,
    ch1_freq: 1000,
    ch1_slew: 0,
    ch1_step: 0,
    ch1_phase: 0,
    ch1_mlo: 0,
    ch1_mhi: DAC_MAX,

    amp_gain_db: 6,
    amp_enabled: 1,
    amp_comp: 2, // 4:1 default
    amp_max_gain: 30,
    muted: 0,
    vplus_mv: 5000,
    sleeping: 0,
  },

  controls: [
    { type: 'slider', field: 'ch0_code', label: 'CH0 DAC code', min: 0, max: 4095, step: 1 },
    { type: 'slider', field: 'ch1_code', label: 'CH1 DAC code', min: 0, max: 4095, step: 1 },
    {
      type: 'slider',
      field: 'amp_gain_db',
      label: 'Amp gain',
      min: -28,
      max: 30,
      step: 1,
      unit: 'dB',
    },
    {
      type: 'slider',
      field: 'vplus_mv',
      label: 'V+ supply',
      min: 2500,
      max: 5500,
      step: 50,
      unit: 'mV',
    },
    { type: 'toggle', field: 'amp_enabled', label: 'Amps enabled' },
    { type: 'toggle', field: 'muted', label: 'Mute' },
    { type: 'toggle', field: 'ch0_wave_on', label: 'CH0 function gen' },
    { type: 'toggle', field: 'ch1_wave_on', label: 'CH1 function gen' },
    { type: 'toggle', field: 'sleeping', label: 'Sleep' },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_drive_a_2_find: () => ({ scalar: DAC_ADDR }),
    tile_drive_a_2_init: () => ({
      scalar: 0,
      nextState: { amp_enabled: 1, amp_gain_db: 6, muted: 0, sleeping: 0 },
    }),
    tile_drive_a_2_sleep: () => ({ nextState: { sleeping: 1 } }),
    tile_drive_a_2_wake: () => ({ nextState: { sleeping: 0 } }),
    tile_drive_a_2_reset: () => ({
      nextState: { ch0_code: 0, ch1_code: 0, ch0_wave_on: 0, ch1_wave_on: 0, muted: 0 },
    }),

    // ── DAC output ──
    tile_drive_a_2_set: ({ args }) =>
      chPatchResult(args, 'code', clamp(pick(args, 1, 0), 0, DAC_MAX)),
    tile_drive_a_2_set_mv: ({ state, args }) => {
      const ch = clamp(pick(args, 0, 0), 0, 1);
      const gain = ch === 0 ? state.ch0_gain : state.ch1_gain;
      const vref = GAIN_FS_MV[clamp(gain, 0, 5)];
      const code = clamp(Math.round((pick(args, 1, 0) * 4096) / vref), 0, DAC_MAX);
      return { nextState: chPatch(ch, 'code', code) };
    },
    tile_drive_a_2_get: ({ state, args }) => ({
      scalar: codeOf(state, clamp(pick(args, 0, 0), 0, 1)),
    }),
    tile_drive_a_2_set_gain: ({ args }) =>
      chPatchResult(args, 'gain', clamp(pick(args, 1, 0), 0, 5)),

    // ── DAC function generator ──
    tile_drive_a_2_set_waveform: ({ args }) => chPatchResult(args, 'wave', pick(args, 1, WAVE_OFF)),
    tile_drive_a_2_start_waveform: ({ args }) => ({
      nextState: chPatch(pick(args, 0, 0), 'wave_on', 1),
    }),
    tile_drive_a_2_stop_waveform: ({ args }) => ({
      nextState: chPatch(pick(args, 0, 0), 'wave_on', 0),
    }),
    tile_drive_a_2_set_slew_rate: ({ args }) => chPatchResult(args, 'slew', pick(args, 1, 0)),
    tile_drive_a_2_set_code_step: ({ args }) => chPatchResult(args, 'step', pick(args, 1, 0)),
    tile_drive_a_2_set_margins: ({ args }) => {
      const ch = pick(args, 0, 0);
      return {
        nextState: {
          ...chPatch(ch, 'mlo', pick(args, 1, 0)),
          ...chPatch(ch, 'mhi', pick(args, 2, DAC_MAX)),
        },
      };
    },
    tile_drive_a_2_set_phase: ({ args }) => chPatchResult(args, 'phase', pick(args, 1, 0)),
    tile_drive_a_2_set_waveform_params: ({ args }) =>
      chPatchResult(args, 'freq', pick(args, 1, 1000)),

    // ── amps (shared 0x58 — affect both) ──
    tile_drive_a_2_amp_set_gain: ({ args }) => ({
      nextState: { amp_gain_db: clamp(pick(args, 0, 6), -28, 30) },
    }),
    tile_drive_a_2_amp_get_gain: ({ state }) => ({ scalar: state.amp_gain_db }),
    tile_drive_a_2_amp_enable: () => ({ nextState: { amp_enabled: 1 } }),
    tile_drive_a_2_amp_disable: () => ({ nextState: { amp_enabled: 0 } }),
    tile_drive_a_2_amp_set_agc: ({ args }) => ({
      nextState: {
        amp_comp: clamp(pick(args, 0, 2), 0, 3),
        amp_max_gain: clamp(pick(args, 1, 30), 18, 30),
      },
    }),
    // FUNC_CTRL readback: bit5 ~ amp enabled (SWS=0); compression in low bits.
    tile_drive_a_2_amp_read_status: ({ state }) => ({
      scalar: (state.amp_enabled ? 0x20 : 0) | (state.amp_comp & 0x03),
    }),

    // ── status / NVM / raw ──
    tile_drive_a_2_read_status: () => ({ scalar: 0 }), // no fault modeled
    tile_drive_a_2_nvm_save: () => ({ nextState: {} }),
    tile_drive_a_2_nvm_reload: () => ({ nextState: {} }),
    tile_drive_a_2_read_reg: ({ args }) => ({ scalar: pick(args, 0, 0) === 0 ? DAC_ADDR : 0 }),
    tile_drive_a_2_write_reg: () => ({ nextState: {} }),

    // ── tier-2 helpers ──
    tile_drive_a_2_play_tone: ({ args }) => {
      const ch = pick(args, 0, 0);
      return {
        nextState: {
          ...chPatch(ch, 'wave', WAVE_SINE),
          ...chPatch(ch, 'wave_on', 1),
          ...chPatch(ch, 'freq', pick(args, 1, 1000)),
        },
      };
    },
    tile_drive_a_2_play_silence: ({ args }) => {
      const ch = pick(args, 0, 0);
      return { nextState: { ...chPatch(ch, 'wave_on', 0), ...chPatch(ch, 'code', 2048) } };
    },
    tile_drive_a_2_play_chirp: ({ args }) => {
      const ch = pick(args, 0, 0);
      return { nextState: { ...chPatch(ch, 'wave', WAVE_SINE), ...chPatch(ch, 'wave_on', 1) } };
    },
    tile_drive_a_2_set_volume_pct: ({ args }) => ({
      nextState: {
        amp_gain_db: Math.round(-28 + clamp(pick(args, 1, 100), 0, 100) * 0.58),
        muted: 0,
      },
    }),
    tile_drive_a_2_mute: () => ({ nextState: { muted: 1 } }),
    tile_drive_a_2_unmute: () => ({ nextState: { muted: 0 } }),
  },

  provenance: {
    // canonical — datasheet/driver-accurate
    tile_drive_a_2_find: 'canonical', // DAC I2C 0x49
    tile_drive_a_2_set_mv: 'canonical', // code = mv·4096/VREF
    tile_drive_a_2_get: 'canonical',
    tile_drive_a_2_set_gain: 'canonical', // VREF multiplier table
    tile_drive_a_2_set_waveform: 'canonical', // function-gen wave codes
    tile_drive_a_2_amp_set_gain: 'canonical', // -28..+30 dB AGC gain reg
    tile_drive_a_2_amp_enable: 'canonical',
    tile_drive_a_2_amp_disable: 'canonical',
    // inferred — obvious from the driver; signal/level modeled
    tile_drive_a_2_init: 'inferred',
    tile_drive_a_2_sleep: 'inferred',
    tile_drive_a_2_wake: 'inferred',
    tile_drive_a_2_reset: 'inferred',
    tile_drive_a_2_set: 'inferred',
    tile_drive_a_2_start_waveform: 'inferred',
    tile_drive_a_2_stop_waveform: 'inferred',
    tile_drive_a_2_set_slew_rate: 'inferred',
    tile_drive_a_2_set_code_step: 'inferred',
    tile_drive_a_2_set_margins: 'inferred',
    tile_drive_a_2_set_phase: 'inferred',
    tile_drive_a_2_set_waveform_params: 'inferred',
    tile_drive_a_2_amp_get_gain: 'inferred',
    tile_drive_a_2_amp_set_agc: 'inferred', // struct arg flattened to comp/max-gain
    tile_drive_a_2_amp_read_status: 'inferred',
    tile_drive_a_2_read_status: 'inferred',
    tile_drive_a_2_nvm_save: 'inferred',
    tile_drive_a_2_nvm_reload: 'inferred',
    tile_drive_a_2_play_tone: 'inferred',
    tile_drive_a_2_play_silence: 'inferred',
    tile_drive_a_2_play_chirp: 'inferred',
    tile_drive_a_2_set_volume_pct: 'inferred',
    tile_drive_a_2_mute: 'inferred',
    tile_drive_a_2_unmute: 'inferred',
    // hallucinated — opaque register access
    tile_drive_a_2_read_reg: 'hallucinated',
    tile_drive_a_2_write_reg: 'hallucinated',
    power: 'inferred', // audio output modeled; amp quiescent + max-output canonical
  },

  // Differential Class-D outputs: per-channel drive envelope 0..1.
  padOutputs(state) {
    const o0 = outLevel(state, 0);
    const o1 = outLevel(state, 1);
    return { 'OUT.0+': o0, 'OUT.0-': o0, 'OUT.1+': o1, 'OUT.1-': o1 };
  },

  // Electrical. Single V+ rail (pad 10) feeds the DAC + both amps. Audio output
  // power dominates: per channel P_out = level²·Pmax(V+), drawn at ~90% Class-D
  // efficiency. Speaker outputs on pads 7/6 (amp0) and 9/8 (amp1).
  power(state) {
    const vplus_v = state.vplus_mv / 1000;
    let drawUa: number;
    if (state.sleeping === 1) {
      drawUa = I_DAC_SLEEP_UA + 2 * I_AMP_SHUTDOWN_UA;
    } else {
      const ampQ = state.amp_enabled === 1 ? 2 * I_AMP_ACTIVE_UA : 2 * I_AMP_SHUTDOWN_UA;
      const pmax = AMP_PMAX_W * (vplus_v / 5) * (vplus_v / 5); // scales with V+²
      const o0 = outLevel(state, 0);
      const o1 = outLevel(state, 1);
      const audioW = (o0 * o0 + o1 * o1) * pmax;
      const audioUa = (audioW / (AMP_EFF * vplus_v)) * 1e6;
      drawUa = I_DAC_ACTIVE_UA + ampQ + audioUa;
    }

    const o0 = outLevel(state, 0);
    const o1 = outLevel(state, 1);
    return {
      draw_ua: Math.round(drawUa),
      rails: [
        {
          name: 'V+',
          role: 'supply',
          v_mv: state.vplus_mv,
          i_ua: Math.round(drawUa),
          pads: ['10'],
          note: 'DAC + 2× amp + audio',
        },
        {
          name: 'OUT.0',
          role: 'output',
          v_mv: Math.round(o0 * state.vplus_mv),
          pads: ['7', '6'],
          note: 'amp0 Class-D speaker out',
        },
        {
          name: 'OUT.1',
          role: 'output',
          v_mv: Math.round(o1 * state.vplus_mv),
          pads: ['9', '8'],
          note: 'amp1 Class-D speaker out',
        },
      ],
    };
  },
};

// Helper used by several DAC setters: apply args[1]-derived value to the channel
// in args[0] (low-level DAC API uses channel 0/1).
function chPatchResult(args: number[], base: string, value: number) {
  const ch = args.length > 0 && Number.isFinite(args[0]) ? args[0] : 0;
  const out: Record<string, number> = {};
  for (const c of ch === 2 ? [0, 1] : [Math.max(0, Math.min(1, ch))]) out[`ch${c}_${base}`] = value;
  return { nextState: out };
}

export default sim;
